<?php require_once __DIR__.'/../includes/permissions.php';require_permission('vaccinations.view');$u=current_user();$pdo=db();if($_SERVER['REQUEST_METHOD']==='GET'){ $q=$pdo->query('SELECT v.id,r.patient_id,v.vaccine,v.dose,v.administered_date,v.status FROM vaccinations v JOIN residents r ON r.id=v.resident_id WHERE v.status="Active" ORDER BY v.administered_date DESC LIMIT 300');json_response(['success'=>true,'data'=>$q->fetchAll()]);}if($_SERVER['REQUEST_METHOD']==='POST'){require_permission('vaccinations.create');$d=json_decode(file_get_contents('php://input'),true)?:$_POST;$q=$pdo->prepare('INSERT INTO vaccinations(resident_id,vaccine,dose,administered_date,administered_by,notes) VALUES(?,?,?,?,?,?)');$q->execute([(int)$d['resident_id'],$d['vaccine'],$d['dose']??null,$d['administered_date'],$u['id'],$d['notes']??null]);json_response(['success'=>true,'id'=>(int)$pdo->lastInsertId()],201);}json_response(['success'=>false,'message'=>'Unsupported request'],405);
